// spec: specs/orders.md (раздел «#1f768e — тост нового заказа не закрывает кнопки») · кейс .qa/tests/orders/ord-35-new-order-toast-no-overlap.md
// seed: tests/seed.admin.spec.ts (+ buyer через asUser)
// #1f768e (עבר QA 25.10; c31d763, e9ba7e1): admin на /orders внизу страницы (1440×900 и 390), buyer отправляет заказ →
// тост «התקבלה הזמנה חדשה · #N · test» в левом нижнем углу; пока он на экране, «⋮» последней строки и кнопки пагинации —
// сами верхние элементы в своей точке (elementFromPoint), «⋮» открывает меню строки (а не заказ из тоста);
// после ✕ страница возвращается (scrollY / scrollHeight как до тоста); звонок — AudioContext.createOscillator().start (spy).
// Данные: товар QA-AUTO-1f76-<ts> (₪1, остаток 5), по заказу «QA-AUTO-1f76-<ts>-<n>» на тест; afterAll — заказы отклоняются,
// товар удаляется. Корзина buyer общая → @orders, не параллельно с другими тестами корзины. Опрос заказов ~20 с — тест долгий.
import { test, expect } from '../../fixtures';
import type { Page, Locator } from '@playwright/test';
import { auth, createStockedProduct, placeOrder, cleanup } from './_qa-order';

test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-1f76-${TS}`;
let productId: string | undefined;
const orderNos: string[] = [];

type Win = Window & { __osc?: number };

/** Spy на звук: считаем вызовы start() у осцилляторов (до загрузки страницы). */
async function spyBell(page: Page) {
  await page.addInitScript(() => {
    const w = window as unknown as Win & { webkitAudioContext?: typeof AudioContext };
    w.__osc = 0;
    for (const AC of [w.AudioContext, w.webkitAudioContext]) {
      if (!AC || (AC.prototype as unknown as { __qaSpy?: boolean }).__qaSpy) continue;
      (AC.prototype as unknown as { __qaSpy?: boolean }).__qaSpy = true;
      const orig = AC.prototype.createOscillator;
      AC.prototype.createOscillator = function (this: AudioContext) {
        const osc = orig.call(this);
        const start = osc.start.bind(osc);
        osc.start = (...a: Parameters<OscillatorNode['start']>) => { w.__osc = (w.__osc ?? 0) + 1; return start(...a); };
        return osc;
      };
    }
  });
}

/** Центр элемента — это он сам (или его потомок), а не тост поверх. */
const onTop = (l: Locator) =>
  l.evaluate((el) => {
    const r = el.getBoundingClientRect();
    const hit = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    return !!hit && (hit === el || el.contains(hit));
  });

const scrollState = (page: Page) => page.evaluate(() => ({ y: Math.round(scrollY), h: document.documentElement.scrollHeight }));

async function runScenario(admin: Page, buyer: Page, tag: string) {
  await spyBell(admin);
  await admin.goto('/orders');
  await expect(admin.getByRole('heading', { level: 1, name: 'הזמנות' })).toBeVisible({ timeout: 30_000 });
  const rows = admin.getByRole('button', { name: /^#\d+ / });
  await expect(rows.first()).toBeVisible({ timeout: 30_000 });
  await expect(admin.getByRole('button', { name: 'העמוד הבא' })).toBeVisible();
  // жест пользователя (звук разрешается браузером только после клика) — клик по заголовку, ничего не открывает
  await admin.getByRole('heading', { level: 1, name: 'הזמנות' }).click();
  await admin.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
  await expect.poll(async () => admin.evaluate(() => Math.ceil(scrollY + innerHeight) >= document.documentElement.scrollHeight - 1)).toBe(true);
  const before = await scrollState(admin);

  const no = await placeOrder(buyer, [{ id: productId!, name: P, qty: 1 }], `${P}-${tag}`);
  orderNos.push(no);

  // тост именно об этом заказе (цикл опроса ~20 с)
  const toast = admin.getByText('התקבלה הזמנה חדשה').locator(`xpath=ancestor::*[contains(normalize-space(.), "#${no}")][1]`);
  await expect(toast.first()).toBeVisible({ timeout: 60_000 });
  const t = toast.first();
  await expect(t).toContainText('test');

  // левый нижний угол
  const vp = admin.viewportSize()!;
  const tb = (await t.boundingBox())!;
  expect(tb.x + tb.width / 2, 'тост в левой половине экрана').toBeLessThan(vp.width / 2);
  expect(tb.y + tb.height, 'тост внизу экрана').toBeGreaterThan(vp.height * 0.6);

  // «⋮» последней строки и пагинация — сверху, не под тостом (после сдвига страницы)
  const lastRow = rows.last();
  const kebab = lastRow.locator('button').last();
  await kebab.scrollIntoViewIfNeeded();
  await expect.poll(() => onTop(kebab), { timeout: 5_000, message: '«⋮» последней строки не закрыт тостом' }).toBe(true);
  for (const name of ['העמוד הבא', 'העמוד הקודם', '1']) {
    const b = admin.getByRole('button', { name, exact: true });
    if (!(await b.count())) continue;
    await expect.poll(() => onTop(b), { timeout: 5_000, message: `пагинация «${name}» не закрыта тостом` }).toBe(true);
  }
  await expect(t, 'проверки выше сделаны, пока тост на экране').toBeVisible();

  // «⋮» открывает меню строки, а не заказ из тоста
  await kebab.click();
  await expect(admin.getByRole('menuitem').first().or(admin.getByRole('menu'))).toBeVisible({ timeout: 10_000 });
  await expect(admin).toHaveURL(/\/orders\/?$/);
  await admin.keyboard.press('Escape');

  // звонок
  await expect.poll(() => admin.evaluate(() => (window as unknown as Win).__osc ?? 0), { timeout: 10_000, message: 'прозвучал колокольчик (oscillator.start)' }).toBeGreaterThan(0);

  // ✕ — тост закрыт, страница на месте
  if (await t.isVisible()) {
    const close = t.getByRole('button', { name: /סגור|סגירה|close/i }).or(t.locator('button[aria-label]')).last();
    await close.click();
  }
  await expect(admin.getByText('התקבלה הזמנה חדשה')).toHaveCount(0, { timeout: 15_000 });
  await expect.poll(async () => {
    const s = await scrollState(admin);
    return Math.abs(s.h - before.h) <= 2 && Math.abs(s.y - before.y) <= 2;
  }, { timeout: 5_000, message: `scrollY/scrollHeight вернулись к ${JSON.stringify(before)}` }).toBe(true);
}

test.describe('orders — התראת הזמנה חדשה לא מסתירה את «⋮» ואת הדפדוף (#1f768e)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), baseURL: test.info().project.use.baseURL, locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    try {
      productId = await createStockedProduct(await ctx.newPage(), P, `QA1F76${TS}`, 1, 5);
    } finally {
      await ctx.close();
    }
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(240_000);
    await cleanup(browser, orderNos, productId ? [P] : []);
  });

  test('1440×900, סוף העמוד: «⋮» של השורה האחרונה והדפדוף מעל ההתראה, «⋮» פותח תפריט, צליל, ✕ מחזיר את העמוד #1f768e @desktop @orders @data', async ({ asUser }) => {
    test.setTimeout(240_000);
    test.skip(!productId, 'товар не создан');
    const admin = await asUser('admin');
    const buyer = await asUser('buyer');
    await admin.setViewportSize({ width: 1440, height: 900 });
    await runScenario(admin, buyer, 'd');
  });

  test('390, גלילה עד הסוף: «⋮» של השורה האחרונה והדפדוף לא מתחת להתראה #1f768e @iphone @orders @data', async ({ asUser }) => {
    test.setTimeout(240_000);
    test.skip(!productId, 'товар не создан');
    const admin = await asUser('admin');
    const buyer = await asUser('buyer');
    await admin.setViewportSize({ width: 390, height: 844 });
    await runScenario(admin, buyer, 'm');
  });
});
